python - <<'PY'
import numpy as np, cv2
from rcb_brush import Session
s=Session(instance='/app/instance.json');s.reset()
for a in np.load('/app/output/trajectory.npz')['actions']:s.step(a)
s.painter.finish(); tar=cv2.cvtColor(s.target_image(),cv2.COLOR_RGB2GRAY)<128
_,lab,stats,_=cv2.connectedComponentsWithStats((cv2.cvtColor(s.target_image(),cv2.COLOR_RGB2GRAY)<80).astype('uint8'))
targs=[]
for i in range(1,len(stats)):
 if stats[i,4]>40:targs.append(lab==i)
# sort matching manually by nearest centers to actual mask centroid
for k,st in enumerate(s.strokes()):
 r0,r1,c0,c1=st['mask_bbox'];a=np.zeros((1024,1024),bool);a[r0:r1,c0:c1]=st['mask']>=128
 cen=np.argwhere(a).mean(axis=0); j=min(range(len(targs)),key=lambda j:np.linalg.norm(np.argwhere(targs[j]).mean(axis=0)-cen));t=targs[j]&tar
 it=(a&t).sum(); un=(a|t).sum(); best=(it/un,0,0)
 for dy in range(-6,7):
  for dx in range(-6,7):
   b=np.zeros_like(a);b[max(0,dy):min(1024,1024+dy),max(0,dx):min(1024,1024+dx)] = a[max(0,-dy):min(1024,1024-dy),max(0,-dx):min(1024,1024-dx)]
   v=(b&t).sum()/(b|t).sum()
   if v>best[0]:best=(v,dx,dy)
 print(k,'center',cen.round(1),'target',j,'IoU',round(it/un,4),'best_shift',best,'recall',round(it/t.sum(),4),'areas',a.sum(),t.sum())
PY

