   v=(b&t).sum()/(b|t).sum()
   if v>best[0]:best=(v,dx,dy)
 print(k,'center',cen.round(1),'target',j,'IoU',round(it/un,4),'best_shift',best,'recall',round(it/t.sum(),4),'areas',a.sum(),t.sum())
